                present[ticker] = data.Bars[symbol]

        # Market-state quantities update continuously for every ticker with a bar.
        if "SPY" in present:
            spy_bar = present["SPY"]
            self.spy_sma_50.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_sma_200.Update(spy_bar.EndTime, spy_bar.Close)

        if "AAPL" in present:
            aapl_bar = present["AAPL"]

            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_bar.Close)

        # If any subscribed ticker is missing, do not evaluate rules today.
        if len(present) != len(self.symbols):
            self._store_previous_values(present)
            return

        if not (self.spy_sma_50.IsReady and
                self.spy_sma_200.IsReady and
                self.aapl_rsi_14.IsReady and
                self.spy_previous_sma_50 is not None and
                self.spy_previous_sma_200 is not None and
                self.aapl_previous_close is not None):
            self._store_previous_values(present)
            return

        spy_close = present["SPY"].Close
        aapl_close = present["AAPL"].Close

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0:
            crossed_below_50 = (
                self.spy_previous_sma_50 <= 0 or
                False
            )
            crossed_below_50 = (
                self._previous_spy_close <= self.spy_previous_sma_50 and
                spy_close < self.spy_sma_50.Current.Value
            )
            if crossed_below_50:
                self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi_14.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0:
            crossed_above_200 = (
                self._previous_spy_close <= self.spy_previous_sma_200 and
                spy_close > self.spy_sma_200.Current.Value
            )
            if crossed_above_200:
                quantity = int((self.Portfolio.TotalPortfolioValue * Decimal("0.40")) / spy_close)
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash_amount = Decimal("20000")
            if self.Portfolio.Cash >= cash_amount:
                quantity = int(cash_amount / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_shares = quantity

        self._store_previous_values(present)

    def _store_previous_values(self, present):
        if "SPY" in present:
            self._previous_spy_close = present["SPY"].Close
            if self.spy_sma_50.IsReady:
                self.spy_previous_sma_50 = self.spy_sma_50.Current.Value
            if self.spy_sma_200.IsReady:
                self.spy_previous_sma_200 = self.spy_sma_200.Current.Value

        if "AAPL" in present:
            self.aapl_previous_close = present["AAPL"].Close
